from pathlib import Path

path=Path('web/index.html')
text=path.read_text(encoding='utf-8')
marker='bridgepoint-v310-install-onboarding'
if marker in text:
    print('v310 install onboarding already applied')
    raise SystemExit(0)

style_anchor='''    #bp-update-toast.show{display:flex;align-items:center;gap:9px}#bp-update-toast .pulse{width:8px;height:8px;border-radius:50%;background:#35d2e8;box-shadow:0 0 12px rgba(53,210,232,.7);flex:0 0 auto}\n'''
style_add=style_anchor+'''    #bp-install-backdrop{display:none;position:fixed;inset:0;z-index:2147483647;background:rgba(2,8,16,.78);backdrop-filter:blur(12px);padding:18px;align-items:center;justify-content:center;font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}\n    #bp-install-backdrop.show{display:flex}\n    #bp-install-card{width:min(520px,100%);max-height:min(760px,calc(100vh - 28px));overflow:auto;border-radius:24px;border:1px solid rgba(53,210,232,.28);background:linear-gradient(155deg,rgba(13,26,43,.99),rgba(7,17,31,.995));box-shadow:0 30px 100px rgba(0,0,0,.62);color:#fff;padding:22px;box-sizing:border-box}\n    .bp-install-top{display:flex;gap:14px;align-items:center}.bp-install-icon{width:58px;height:58px;border-radius:16px;background:linear-gradient(135deg,#35d2e8,#4f7cff);display:grid;place-items:center;font-weight:950;font-size:24px;box-shadow:0 10px 30px rgba(53,210,232,.22)}\n    .bp-install-eyebrow{font-size:10px;letter-spacing:.9px;color:#35d2e8;font-weight:900}.bp-install-title{font-size:22px;line-height:1.08;font-weight:950;margin-top:3px}.bp-install-copy{color:#b6c5d8;font-size:13px;line-height:1.55;margin:16px 0 13px}\n    .bp-install-benefits{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:12px 0 17px}.bp-install-benefit{padding:10px;border-radius:12px;background:rgba(255,255,255,.035);border:1px solid rgba(255,255,255,.065);font-size:10px;color:#b6c5d8}.bp-install-benefit b{display:block;color:#fff;font-size:11px;margin-bottom:2px}\n    #bp-install-steps{padding:13px 14px;border-radius:14px;background:rgba(53,210,232,.055);border:1px solid rgba(53,210,232,.13);margin:0 0 16px}.bp-install-step{display:flex;gap:10px;align-items:flex-start;padding:6px 0}.bp-install-num{width:22px;height:22px;border-radius:50%;display:grid;place-items:center;flex:0 0 auto;background:rgba(53,210,232,.14);color:#35d2e8;font-size:10px;font-weight:950}.bp-install-step-text{font-size:11px;line-height:1.4;color:#d7e1ed}.bp-install-step-text b{color:#fff}\n    .bp-install-actions{display:flex;gap:9px;flex-wrap:wrap}.bp-install-primary,.bp-install-secondary{border:0;border-radius:12px;padding:12px 15px;font-weight:900;font-size:12px;cursor:pointer}.bp-install-primary{background:#35d2e8;color:#07111f;flex:1 1 220px}.bp-install-secondary{background:#122238;color:#d7e1ed;border:1px solid rgba(255,255,255,.10);flex:0 1 auto}.bp-install-note{font-size:9.5px;color:#8196ae;line-height:1.45;margin-top:11px;text-align:center}\n    @media(max-width:560px){#bp-install-backdrop{padding:10px;align-items:flex-end}#bp-install-card{border-radius:22px 22px 16px 16px;padding:18px;max-height:88vh}.bp-install-title{font-size:20px}.bp-install-benefits{grid-template-columns:1fr}.bp-install-primary,.bp-install-secondary{width:100%;flex:1 1 100%}}\n'''
if text.count(style_anchor)!=1:
    raise SystemExit(f'v310 style anchor count {text.count(style_anchor)}')
text=text.replace(style_anchor,style_add,1)

body_anchor='''  <div id="bp-update-toast" role="status" aria-live="polite"><span class="pulse"></span><span id="bp-update-message">BridgePoint is updating…</span></div>\n\n'''
modal=body_anchor+'''  <div id="bp-install-backdrop" role="dialog" aria-modal="true" aria-labelledby="bp-install-title" aria-describedby="bp-install-description">\n    <section id="bp-install-card">\n      <div class="bp-install-top">\n        <div class="bp-install-icon" aria-hidden="true">B</div>\n        <div><div class="bp-install-eyebrow">BRIDGEPOINT APP</div><div class="bp-install-title" id="bp-install-title">Put BridgePoint on your home screen</div></div>\n      </div>\n      <p class="bp-install-copy" id="bp-install-description">BridgePoint is open in your browser. Install it as an app for faster one-tap access, a full-screen workspace, and automatic release updates.</p>\n      <div class="bp-install-benefits">\n        <div class="bp-install-benefit"><b>One tap to open</b>No browser searching or saved link needed.</div>\n        <div class="bp-install-benefit"><b>App-style workspace</b>Opens in its own BridgePoint window.</div>\n        <div class="bp-install-benefit"><b>Stays current</b>BridgePoint checks for new releases automatically.</div>\n      </div>\n      <div id="bp-install-steps" aria-live="polite"></div>\n      <div class="bp-install-actions">\n        <button id="bp-install-primary" class="bp-install-primary" type="button">Install BridgePoint</button>\n        <button id="bp-install-later" class="bp-install-secondary" type="button">Not now</button>\n      </div>\n      <div class="bp-install-note">If you choose “Not now,” BridgePoint will remind you on a future browser sign-in until this device has been installed.</div>\n    </section>\n  </div>\n\n'''
if text.count(body_anchor)!=1:
    raise SystemExit(f'v310 body anchor count {text.count(body_anchor)}')
text=text.replace(body_anchor,modal,1)

script_anchor='''  <script src="flutter_bootstrap.js" async></script>\n'''
install_script='''  <script>\n  /* bridgepoint-v310-install-onboarding */\n  (()=>{\n    const installedKey='bridgepoint_app_installed_v310';\n    const dismissedKey='bridgepoint_install_dismissed_session_v310';\n    const backdrop=document.getElementById('bp-install-backdrop');\n    const primary=document.getElementById('bp-install-primary');\n    const later=document.getElementById('bp-install-later');\n    const steps=document.getElementById('bp-install-steps');\n    let deferredPrompt=null;\n    let shown=false;\n\n    const isIos=()=>/iphone|ipad|ipod/i.test(navigator.userAgent||'');\n    const isAndroid=()=>/android/i.test(navigator.userAgent||'');\n    const isStandalone=()=>window.matchMedia?.('(display-mode: standalone)').matches===true||navigator.standalone===true||document.referrer.startsWith('android-app://');\n    function hasAuthSession(){\n      try{\n        const keys=Object.keys(localStorage).filter(k=>k.startsWith('sb-')&&k.endsWith('-auth-token'));\n        for(const key of keys){\n          const raw=localStorage.getItem(key);if(!raw)continue;\n          const value=JSON.parse(raw);\n          const token=value?.access_token||value?.currentSession?.access_token||value?.session?.access_token;\n          if(token)return true;\n        }\n      }catch(_){ }\n      return false;\n    }\n    function markInstalled(){\n      try{localStorage.setItem(installedKey,'1')}catch(_){ }\n      backdrop?.classList.remove('show');shown=false;\n    }\n    function alreadyInstalled(){\n      if(isStandalone()){markInstalled();return true;}\n      try{return localStorage.getItem(installedKey)==='1'}catch(_){return false}\n    }\n    function dismissedThisSession(){try{return sessionStorage.getItem(dismissedKey)==='1'}catch(_){return false}}\n    function step(n,html){return `<div class="bp-install-step"><span class="bp-install-num">${n}</span><div class="bp-install-step-text">${html}</div></div>`}\n    function renderInstructions(){\n      if(!steps||!primary)return;\n      if(deferredPrompt){\n        primary.style.display='';primary.textContent='Install BridgePoint';\n        steps.innerHTML=step(1,'Tap <b>Install BridgePoint</b> below.')+step(2,'Approve the browser install prompt.')+step(3,'Open BridgePoint from your home screen or app launcher.');\n        return;\n      }\n      if(isIos()){\n        primary.style.display='none';\n        steps.innerHTML=step(1,'Tap the browser <b>Share</b> button (the square with the arrow pointing up).')+step(2,'Choose <b>Add to Home Screen</b>. If you do not see it immediately, scroll the Share menu.')+step(3,'Tap <b>Add</b>. BridgePoint will appear with your other apps.');\n        return;\n      }\n      if(isAndroid()){\n        primary.style.display='none';\n        steps.innerHTML=step(1,'Open your browser menu <b>⋮</b>.')+step(2,'Tap <b>Install app</b> or <b>Add to Home screen</b>.')+step(3,'Confirm <b>Install</b>, then open BridgePoint from your app launcher.');\n        return;\n      }\n      primary.style.display='none';\n      steps.innerHTML=step(1,'Look for the <b>Install</b> icon in your browser address bar, or open the browser menu.')+step(2,'Choose <b>Install BridgePoint</b> / <b>Install app</b>.')+step(3,'Confirm the install. BridgePoint will open in its own app window.');\n    }\n    function showInstall(){\n      if(shown||alreadyInstalled()||dismissedThisSession()||!hasAuthSession())return;\n      shown=true;renderInstructions();backdrop?.classList.add('show');primary?.focus();\n    }\n    async function requestInstall(){\n      if(!deferredPrompt){renderInstructions();return;}\n      const prompt=deferredPrompt;deferredPrompt=null;\n      try{\n        prompt.prompt();\n        const choice=await prompt.userChoice;\n        if(choice?.outcome==='accepted')markInstalled();else{shown=false;backdrop?.classList.remove('show');}\n      }catch(_){renderInstructions()}\n    }\n\n    window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredPrompt=event;renderInstructions();setTimeout(showInstall,150)});\n    window.addEventListener('appinstalled',markInstalled);\n    window.matchMedia?.('(display-mode: standalone)').addEventListener?.('change',event=>{if(event.matches)markInstalled()});\n    primary?.addEventListener('click',requestInstall);\n    later?.addEventListener('click',()=>{try{sessionStorage.setItem(dismissedKey,'1')}catch(_){ }backdrop?.classList.remove('show');shown=false;});\n    backdrop?.addEventListener('click',event=>{if(event.target===backdrop)later?.click()});\n    document.addEventListener('keydown',event=>{if(event.key==='Escape'&&backdrop?.classList.contains('show'))later?.click()});\n\n    if(alreadyInstalled())return;\n    const authWatch=setInterval(()=>{if(alreadyInstalled()){clearInterval(authWatch);return;}if(hasAuthSession()){showInstall();if(shown)clearInterval(authWatch)}},1200);\n    window.addEventListener('load',()=>setTimeout(showInstall,1800));\n    document.addEventListener('visibilitychange',()=>{if(!document.hidden)setTimeout(showInstall,250)});\n    window.bridgePointShowInstallGuide=()=>{try{sessionStorage.removeItem(dismissedKey)}catch(_){ }shown=false;showInstall()};\n  })();\n  </script>\n\n'''+script_anchor
if text.count(script_anchor)!=1:
    raise SystemExit(f'v310 bootstrap anchor count {text.count(script_anchor)}')
text=text.replace(script_anchor,install_script,1)

path.write_text(text,encoding='utf-8')
print('Applied automatic signed-in PWA install onboarding v310.')